export type Recordable = Record<string, unknown>;
export interface TVBoxConfig {
    /** 配置名称/作者信息 */
    name?: string;
    author?: string;
    /** 爬虫 JAR 路径（支持 md5） */
    spider?: string;
    /** 壁纸 URL */
    wallpaper?: string;
    /** Logo */
    logo?: string;
    /** 直播源数组 */
    lives?: Live[];
    /** 视频源/站点数组（最核心部分） */
    sites?: Site[];
    /** 解析接口数组 */
    parses?: Parse[];
    /** 嗅探/规则数组 */
    rules?: Rule[];
    /** DOH 服务器 */
    doh?: Doh[];
    /** 广告域名黑名单 */
    ads?: string[];
}
export interface LiveChannel {
    name: string;
    urls: string[];
    epg?: string;
}
export interface LiveClassic {
    group: string;
    channels: LiveChannel[];
}
export interface LiveFengMi {
    type: number;
    url: string;
    playerType?: number;
}
export type LiveImpl = LiveClassic | LiveFengMi;
export type Live = LiveImpl & {
    name?: string;
    epg?: string;
    logo?: string;
    ua?: string;
    /** 多线路时使用 */
    ext?: Recordable;
};
export interface Site {
    key: string;
    name: string;
    type: number;
    api: string;
    searchable?: number;
    quickSearch?: number;
    filterable?: number;
    changeable?: number;
    timeout?: number;
    playerType?: number | string;
    jar?: string;
    ext?: string | Recordable;
    style?: {
        type?: 'list' | 'rect' | 'cover';
        ratio?: number;
    };
    categories?: string[];
    indexs?: number;
}
export interface Parse {
    name: string;
    url: string;
    type?: number;
    ext?: Recordable;
}
export interface Rule {
    name: string;
    hosts: string[];
    regex?: string[];
    script?: string[];
}
export interface Doh {
    name: string;
    url: string;
    ips?: string[];
}
